  "think": false,
  "format": { "type": "object", "properties": { "needs_personal_data": { "type": "boolean" }, "needs_frontier": { "type": "boolean" }, "reasoning": { "type": "string" } }, "required": ["needs_personal_data", "needs_frontier", "reasoning"] },
  "options": { "temperature": 0 }
}

